"use client";

import { useCallback, useEffect, useState } from "react";
type Review = { id: string; status: string; content: unknown; submittedAt: string | null; student: { name: string | null; email: string }; assignment: { title: string; maxScore: number; group: { name: string } | null } };
export default function TeacherReviewsPage() { const [items, setItems] = useState<Review[]>([]); const [error, setError] = useState(""); const [scores, setScores] = useState<Record<string, string>>({}); const load = useCallback(async () => { const r = await fetch("/api/teacher/reviews", { cache: "no-store" }); const p = await r.json().catch(() => null); if (r.ok) setItems(p.data ?? []); else setError(p?.error ?? "Unable to load reviews."); }, []); useEffect(() => { void load(); }, [load]); const review = async (id: string, revision = false) => { const r = await fetch(`/api/teacher/reviews/${id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(revision ? { needsRevision: true } : { score: Number(scores[id]) }) }); const p = await r.json().catch(() => null); if (!r.ok) { setError(p?.error ?? "Unable to save review."); return; } void load(); }; return <section className="space-y-6"><header><h2 className="text-3xl font-bold">Reviews</h2><p className="mt-2 text-slate-600">Review submitted work and return clear feedback.</p></header>{error ? <p className="rounded-lg bg-red-50 p-3 text-red-800">{error}</p> : null}{items.length === 0 ? <div className="rounded-2xl border border-dashed bg-white p-8 text-slate-600">Nothing is waiting for review.</div> : <div className="space-y-4">{items.map((item) => <article key={item.id} className="rounded-2xl border bg-white p-5"><h3 className="font-bold">{item.assignment.title}</h3><p className="mt-1 text-sm text-slate-600">{item.student.name ?? item.student.email} · {item.assignment.group?.name ?? "Individual"}</p><pre className="mt-3 overflow-auto rounded-lg bg-slate-50 p-3 text-sm">{JSON.stringify(item.content, null, 2)}</pre><div className="mt-4 flex flex-wrap gap-2"><input aria-label={`Score for ${item.assignment.title}`} value={scores[item.id] ?? ""} onChange={(e) => setScores((prev) => ({ ...prev, [item.id]: e.target.value }))} type="number" min="0" max={item.assignment.maxScore} placeholder={`Score / ${item.assignment.maxScore}`} className="w-40 rounded-lg border px-3 py-2"/><button type="button" onClick={() => void review(item.id)} className="rounded-lg bg-blue-700 px-3 py-2 font-semibold text-white">Grade</button><button type="button" onClick={() => void review(item.id, true)} className="rounded-lg border px-3 py-2 font-semibold">Request revision</button></div></article>)}</div>}</section>; }
